    const entry={id:feature.id,name:feature.name,codeLines:feature.codeLines,debt:inherited*importedFraction+Math.max(0,s.debt-remainingImported)*share,verified:true,catalogVersion:project.snapshot.catalogVersion,builds:s.build.count};
