  if(active){active.status='active';result.active=active.id;}
  result.knowledge.synergies=Array.isArray(raw.knowledge?.synergies)?[...new Set(raw.knowledge.synergies.filter(id=>typeof id==='string' && /^[a-z0-9][a-z0-9._:-]{0,299}$/.test(id)))].slice(0,500):[];result.knowledge.testedFeatures=ids(raw.knowledge?.testedFeatures);result.knowledge.genres=ids(raw.knowledge?.genres);
